previewCss:
.darma-loader-darma-b13-circular-saw { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #64748b); width: var(--loader-size, 100px); height: var(--loader-size, 100px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b13-circular-saw .darma-loader-darma-b13-circular-saw__blade { position: relative; width: 88%; height: 88%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 22%, var(--accent-2)) 0 57%, transparent 58%), repeating-conic-gradient(from 0deg, var(--accent) 0 7deg, transparent 7deg 18deg); animation: darma-loader-darma-b13-circular-saw-saw calc(var(--loader-speed, 1s) * .7) linear infinite; }
.darma-loader-darma-b13-circular-saw .darma-loader-darma-b13-circular-saw__blade::after { content: ''; position: absolute; inset: 40%; border-radius: 50%; background: #f8fafc; box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 24%, var(--accent-2)); }
.darma-loader-darma-b13-circular-saw span { position: absolute; bottom: 13%; right: 7%; width: 9%; height: 3%; border-radius: 999px; background: var(--accent); animation: darma-loader-darma-b13-circular-saw-spark calc(var(--loader-speed, 1s) * 1.1) ease-out infinite; }
.darma-loader-darma-b13-circular-saw span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .55); }
@keyframes darma-loader-darma-b13-circular-saw-saw { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b13-circular-saw-spark { 0% { opacity: 0; transform: translate(0, 0) scaleX(.4); } 22% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size, 100px) * .24), calc(var(--loader-size, 100px) * .1)) scaleX(1.7); } }

